-- This migration is hand-authored (not generated by `prisma migrate dev`),
-- because it uses two Postgres features Prisma's schema DSL cannot express
-- yet: partial (filtered) unique indexes and Row-Level Security policies.
-- See docs/DATABASE_DESIGN.md for the full rationale behind both sections.
--
-- Both sections are idempotent and safe to run against a fresh database
-- created from migration 20260717130000_init.

-- =============================================================================
-- 1. PARTIAL UNIQUE INDEXES
--
-- Soft-deleted rows (`deleted_at IS NOT NULL`) must not block reuse of a
-- "unique" value by a new, live row — e.g. a business that deleted itself
-- and re-registers with the same email, or a customer phone number that
-- gets reused. A plain `@@unique` in schema.prisma would enforce
-- uniqueness across soft-deleted rows too, which is wrong here, so these
-- are declared as ordinary (non-unique) `@@index` in schema.prisma and the
-- real uniqueness constraint is this partial index instead.
-- =============================================================================

CREATE UNIQUE INDEX "businesses_slug_unique_active"
  ON "businesses" ("slug")
  WHERE "deleted_at" IS NULL;

CREATE UNIQUE INDEX "businesses_email_unique_active"
  ON "businesses" ("email")
  WHERE "deleted_at" IS NULL;

CREATE UNIQUE INDEX "branches_business_id_code_unique_active"
  ON "branches" ("business_id", "code")
  WHERE "deleted_at" IS NULL;

CREATE UNIQUE INDEX "users_email_unique_active"
  ON "users" ("email")
  WHERE "deleted_at" IS NULL;

CREATE UNIQUE INDEX "customers_business_id_phone_unique_active"
  ON "customers" ("business_id", "phone")
  WHERE "deleted_at" IS NULL;

CREATE UNIQUE INDEX "queues_branch_id_name_unique_active"
  ON "queues" ("branch_id", "name")
  WHERE "deleted_at" IS NULL;

-- Role uniqueness is split in two, because `business_id` itself is
-- nullable (NULL = system role shipped by QueueFlow, shared by every
-- tenant; non-NULL = a business's own custom role) and Postgres treats
-- every NULL as distinct for a normal unique index, which would silently
-- allow duplicate system-role names.
CREATE UNIQUE INDEX "roles_system_name_unique_active"
  ON "roles" ("name")
  WHERE "business_id" IS NULL AND "deleted_at" IS NULL;

CREATE UNIQUE INDEX "roles_business_id_name_unique_active"
  ON "roles" ("business_id", "name")
  WHERE "business_id" IS NOT NULL AND "deleted_at" IS NULL;

-- At most one "live" (non-terminal) Subscription per business — see
-- docs/DATABASE_DESIGN.md "Why there's no Business.activeSubscriptionId
-- pointer". History (CANCELLED/EXPIRED rows) is unaffected.
CREATE UNIQUE INDEX "subscriptions_business_id_live_unique"
  ON "subscriptions" ("business_id")
  WHERE "status" IN ('TRIALING', 'ACTIVE', 'PAST_DUE');

-- =============================================================================
-- 2. ROW-LEVEL SECURITY (illustrative — see docs/DATABASE_DESIGN.md
--    "Row-Level Security: how far this goes")
--
-- Every table with a direct `business_id` column gets a tenant-isolation
-- policy: a row is visible/writable only when `business_id` equals the
-- Postgres session variable `app.current_business_id`. The API layer
-- (out of scope for this task) is responsible for running
-- `SET app.current_business_id = '<uuid>'` (or
-- `SET LOCAL ...` inside a transaction) once per request, using the
-- tenant resolved from the authenticated staff user's session — never a
-- client-supplied value.
--
-- `FORCE ROW LEVEL SECURITY` makes the policy apply even to the table
-- owner, so a role with BYPASSRLS (see below) is required for
-- migrations, seeding, and platform-admin (admin_panel) access across
-- every tenant.
-- =============================================================================

DO $$
DECLARE
  rls_table text;
BEGIN
  FOREACH rls_table IN ARRAY ARRAY[
    'business_settings', 'branches', 'holidays', 'users', 'roles',
    'user_roles', 'staff_invitations', 'queues', 'queue_entries',
    'qr_codes', 'customers', 'notifications', 'feedback', 'subscriptions',
    'audit_logs'
  ]
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY;', rls_table);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY;', rls_table);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (business_id = current_setting(''app.current_business_id'', true)::uuid);',
      rls_table
    );
  END LOOP;
END $$;

-- A dedicated, non-superuser role for anything that must see across every
-- tenant (Prisma migrations, `prisma db seed`, and the platform-level
-- admin_panel connection pool). Guarded so this migration is safe to
-- re-run / apply on a cluster where the role already exists.
--
-- IMPORTANT: this only creates the role. Granting it BYPASSRLS and
-- pointing the right connection pool (migrations vs. tenant-scoped API
-- traffic) at the right Postgres role is a deployment/ops concern for
-- whichever hosting platform is chosen later — see docs/DATABASE_DESIGN.md.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'queueflow_platform_admin') THEN
    EXECUTE 'CREATE ROLE queueflow_platform_admin BYPASSRLS NOSUPERUSER NOCREATEDB NOCREATEROLE LOGIN';
  END IF;
END $$;
